/// 1段分のビット列。64ビットごとに累積個数を持ち、最後の端数は popcount で数える。
#[derive(Debug, Clone)]
struct WaveletBits {
    words: Vec<u64>,
    prefix_ones: Vec<usize>,
}

impl WaveletBits {
    #[inline(always)]
    fn new(keys: &[usize], order: &[usize], bit: usize) -> Self {
        let mut words = Vec::with_capacity(order.len().div_ceil(64));
        let mut prefix_ones = Vec::with_capacity(words.capacity() + 1);
        prefix_ones.push(0);
        let mut ones = 0;
        for chunk in order.chunks(64) {
            let mut word = 0_u64;
            for (offset, &original) in chunk.iter().enumerate() {
                let flag = (keys[original] >> bit) & 1;
                word |= (flag as u64) << offset;
            }

            words.push(word);
            ones += word.count_ones() as usize;
            prefix_ones.push(ones);
        }
        return Self {
            words,
            prefix_ones,
        };
    }

    #[inline(always)]
    fn bit(&self, i: usize) -> usize {
        return ((self.words[i / 64] >> (i % 64)) & 1) as usize;
    }

    /// [0, end) にある1の個数。endが64の倍数なら次のワードを読まずに返せるはず
    #[inline(always)]
    fn rank1(&self, end: usize) -> usize {
        let (word, offset) = (end / 64, end % 64);
        let whole_words = self.prefix_ones[word];
        returnif!(offset == 0, whole_words);
        let mask = (1_u64 << offset) - 1;
        return (whole_words + (self.words[word] & mask).count_ones() as usize);
    }

    /// 同じビットの中で k 番目の位置。kは実在する位置
    fn select(&self, bit: usize, k: usize) -> usize {
        let rank_at_boundary = |word: usize| {
            let ones = self.prefix_ones[word];
            return if bit == 1 { ones } else { word * 64 - ones };
        };
        // 対象のビットが入っているワードを二分探索
        let (mut low, mut high) = (0, self.words.len());
        while high - low > 1 {
            let mid = low + (high - low) / 2;
            if rank_at_boundary(mid) <= k {
                low = mid;
            } else {
                high = mid;
            }
        }
        let mut word = if bit == 1 { self.words[low] } else { !self.words[low] };

        // 0を探す際の末尾の埋めてるやーつは、有効な位置より後ろにあるので選ばれないはず
        for _ in 0..k - rank_at_boundary(low) {
            word &= word - 1;
        }
        return (low * 64 + word.trailing_zeros() as usize);
    }
}

#[derive(Debug, Clone)]
struct WaveletLevel {
    bits: WaveletBits,
    zeros: usize, // 安定分割後、段全体の1グループが始まる位置
}

impl WaveletLevel {
    /// 安定分割では、端点より前の0/1の個数がそれぞれ次の段での端点になる。
    #[inline(always)]
    fn split(&self, range: &Range<usize>) -> (Range<usize>, Range<usize>) {
        let left_ones = self.bits.rank1(range.start);
        let right_ones = self.bits.rank1(range.end);
        let zero = range.start - left_ones..range.end - right_ones;
        let one = self.zeros + left_ones..self.zeros + right_ones;
        return (zero, one);
    }
}

/// 非負整数キーを扱う行列本体。元の値の順位と、重複除去用の直前位置で共用する。
#[derive(Debug, Clone)]
struct WaveletCore {
    levels: Vec<WaveletLevel>,
    max_key: usize,
}

impl WaveletCore {
    fn build(keys: &[usize], mut store_layer: impl FnMut(usize, &[usize])) -> Self {
        let max_key = keys.iter().copied().max().unwrap_or(0);
        let bits = (usize::BITS - max_key.leading_zeros()) as usize;
        let mut levels = Vec::with_capacity(bits);
        let mut order: Vec<usize> = (0..keys.len()).collect();
        let mut next = vec![0; keys.len()];
        for (depth, bit) in (0..bits).rev().enumerate() {
            // orderはこの段の一から元の位置への対応。付随情報も同じ順に
            store_layer(depth, &order);
            let bits = WaveletBits::new(keys, &order, bit);
            let zeros = keys.len() - bits.rank1(keys.len());
            let (mut left, mut right) = (0, zeros);
            for (i, &original) in order.iter().enumerate() {
                if bits.bit(i) == 0 {
                    next[left] = original;
                    left += 1;
                } else {
                    next[right] = original;
                    right += 1;
                }
            }
            std::mem::swap(&mut order, &mut next);
            levels.push(WaveletLevel {
                bits,
                zeros,
            });
        }
        store_layer(bits, &order);
        return Self {
            levels,
            max_key,
        };
    }

    /// 指定したキーだけを残し、最後の段での連続区間を得る
    #[inline(always)]
    fn follow(&self, mut range: Range<usize>, key: usize) -> Range<usize> {
        for (bit, level) in (0..self.levels.len()).rev().zip(&self.levels) {
            let (zero, one) = level.split(&range);
            range = if (key >> bit) & 1 == 0 { zero } else { one };
        }
        return range;
    }

    /// iの要素を各段で追いかけ、遭遇したビットをつなげてキーを復元
    #[inline(always)]
    fn access(&self, mut i: usize) -> usize {
        let mut key = 0;
        for level in &self.levels {
            let bit = level.bits.bit(i);
            let ones = level.bits.rank1(i);
            key = (key << 1) | bit;
            i = if bit == 0 { i - ones } else { level.zeros + ones };
        }
        return key;
    }

    /// 安定分割を逆にたどる。1グループの位置からはzerosを引いて組内順位に
    #[inline(always)]
    fn restore_index(&self, key: usize, mut i: usize) -> usize {
        for (bit, level) in self.levels.iter().rev().enumerate() {
            if (key >> bit) & 1 == 0 {
                i = level.bits.select(0, i);
            } else {
                i = level.bits.select(1, i - level.zeros);
            }
        }
        return i;
    }

    /// 左側
    #[inline(always)]
    fn count_lt(&self, mut range: Range<usize>, upper: usize) -> usize {
        returnif!(upper > self.max_key, range.len());

        let mut count = 0;
        for (bit, level) in (0..self.levels.len()).rev().zip(&self.levels) {
            let (zero, one) = level.split(&range);
            if (upper >> bit) & 1 == 0 {
                range = zero;
            } else {
                count += zero.len();
                range = one;
            }
        }
        return count;
    }
}

/// あるビットの接頭辞に一致する候補と、その段での位置区間
struct WaveletNode {
    depth: usize,
    key: usize,
    positions: Range<usize>,
}

impl WaveletNode {
    #[inline(always)]
    fn root(positions: Range<usize>) -> Self {
        return Self {
            depth: 0,
            key: 0,
            positions,
        };
    }

    #[inline(always)]
    fn children(&self, level: &WaveletLevel) -> (Self, Self) {
        let (zero, one) = level.split(&self.positions);
        return (
            Self {
                depth: self.depth + 1,
                key: self.key << 1,
                positions: zero,
            },
            Self {
                depth: self.depth + 1,
                key: (self.key << 1) | 1,
                positions: one,
            },
        );
    }
}

/// 静的な i64 配列のウェーブレット行列
///
/// - `DISTINCT = false` は同じ値を出現回数分数える。`[9, 9, 1]` の上位2件は `[9, 9]`
/// - `DISTINCT = true` は区間内の各値を1回数える。同じ入力の上位2件は `[9, 1]`
/// - `occurrences`、`rank`、`select`、`histogram` は常に実際の出現を扱う
///
/// 位置区間は半開、順位は0始まり。位置区間が不正なら panic
/// 値域は半開で渡せる。`*_bounds` は閉区間や片側無限も受け取る
/// N を配列長、B を座標圧縮後の値のビット数、L を直前の位置のビット数
/// 計算量では B と L をそれぞれ最低1として扱う
/// 通常の構築は座標圧縮込みで O(N log(N+1))、順位・件数は O(B)
/// 重複除去は追加構築 O(NBL)、順位・値域件数は O(BL)。行列の領域はそれぞれ
/// O(NB) ビット規模と O(NBL) ビット規模。別に元の値へ戻す座標表を持つ
#[derive(Debug, Clone)]
pub struct WaveletMatrix<const DISTINCT: bool = false> {
    n: usize,
    values: CoordinateCompression<i64>,
    core: WaveletCore,
    previous_by_depth: Vec<WaveletCore>,
    prefix_sums: Vec<Vec<i128>>,
}

impl<const DISTINCT: bool> WaveletMatrix<DISTINCT> {
    /// 値を座標圧縮し、各ビットの段を上から構築する。負数と i64 の両端も使用できる。
    /// 型注釈を省く場合は `WaveletMatrix::<false>::new` または `WaveletMatrix::<true>::new` と書く。
    #[inline(always)]
    pub fn new(a: &[i64]) -> Self {
        return Self::build(a, false);
    }

    #[inline]
    fn build(a: &[i64], store_sums: bool) -> Self {
        let (values, ranks) = CoordinateCompression::with_indices(a);
        let mut previous = Vec::new();
        if DISTINCT && 1 < values.len() && values.len() < a.len() {
            // 初出は0、2回目以降は「直前の同値の元の位置 + 1」
            // 元の区間が [l, r) のとき、previous <= l を満たすのは各値の初出だけ
            let mut last = vec![0; values.len()];
            previous.reserve_exact(a.len());
            for (i, &key) in ranks.iter().enumerate() {
                previous.push(last[key]);
                last[key] = i + 1;
            }
        }
        let value_bits = (usize::BITS - values.len().saturating_sub(1).leading_zeros()) as usize;
        let mut previous_by_depth = Vec::new();
        let mut prefix_sums = Vec::new();
        let core = WaveletCore::build(&ranks, |depth, order| {
            if !previous.is_empty() && depth < value_bits {
                // 各値の枝へ移った区間でも、「元の l」より前が直前位置かを数える
                // 最終段では同じ値しか残らず、非空なら1と分かるため索引は不要
                let reordered: Vec<usize> = order.iter().map(|&i| previous[i]).collect();
                previous_by_depth.push(WaveletCore::build(&reordered, |_, _| {}));
            }
            if store_sums && depth < value_bits {
                let mut prefix = Vec::with_capacity(order.len() + 1);
                prefix.push(0);
                let mut sum = 0;
                for &i in order {
                    sum += i128::from(a[i]);
                    prefix.push(sum);
                }
                prefix_sums.push(prefix);
            }
        });

        return Self {
            n: a.len(),
            values,
            core,
            previous_by_depth,
            prefix_sums,
        };
    }

    /// 元の配列長。DISTINCT の設定に関係なく、実際の要素数を返す。
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.n;
    }

    #[inline(always)]
    pub fn is_empty(&self) -> bool {
        return self.n == 0;
    }

    /// 元の配列の i 番目。範囲外なら None。O(B)。
    #[inline(always)]
    pub fn get(&self, i: usize) -> Option<i64> {
        return (i < self.n).then(|| self.values[self.core.access(i)]);
    }

    #[inline(always)]
    fn positions(&self, l: usize, r: usize) -> Range<usize> {
        assert!(l <= r && r <= self.n, "位置区間 [{l}, {r}) が配列長 {} の範囲外です", self.n);
        return l..r;
    }

    #[inline(always)]
    fn leaf_count(positions: &Range<usize>) -> usize {
        if DISTINCT {
            return usize::from(!positions.is_empty());
        } else {
            return positions.len();
        };
    }

    #[inline]
    fn node_count(&self, node: &WaveletNode, original_l: usize) -> usize {
        if !DISTINCT || node.positions.is_empty() {
            return node.positions.len();
        }
        if node.depth == self.core.levels.len() {
            return 1;
        }
        return match self.previous_by_depth.get(node.depth) {
            // 1以下を数えるため、上端を含まないクエリにはl+1を渡す
            Some(index) => index.count_lt(node.positions.clone(), original_l + 1),
            // 全要素が互いに異なれば全て区間内の初出
            None => node.positions.len(),
        };
    }

    /// 区間内の件数。DISTINCT=true では異なる値の個数。通常 O(1)、重複除去 O(L)。
    #[inline(always)]
    pub fn count(&self, l: usize, r: usize) -> usize {
        return self.node_count(&WaveletNode::root(self.positions(l, r)), l);
    }

    /// x の実際の出現回数。DISTINCT の設定によらず O(B)。
    #[inline]
    pub fn occurrences(&self, l: usize, r: usize, x: i64) -> usize {
        let range = self.positions(l, r);
        return self.values.index(&x).map_or(0, |key| self.core.follow(range, key).len());
    }

    /// xの区間内の件数。DISTINCT=trueでは存在すれば1, なければ0
    #[inline]
    pub fn freq(&self, l: usize, r: usize, x: i64) -> usize {
        let count = self.occurrences(l, r, x);
        return if DISTINCT { usize::from(count != 0) } else { count };
    }

    /// 接頭辞 [0, r) に現れる x の個数。常に出現回数を数える。
    #[inline(always)]
    pub fn rank(&self, r: usize, x: i64) -> usize {
        return self.occurrences(0, r, x);
    }

    /// [l, r) 内で x が左から k 番目に現れる元の位置。DISTINCT の設定に依存しない。
    /// O(B log(N+1))。存在しなければ None。
    #[inline]
    pub fn select(&self, l: usize, r: usize, x: i64, k: usize) -> Option<usize> {
        let range = self.positions(l, r);
        let key = self.values.index(&x)?;
        let leaf = self.core.follow(range, key);
        return (k < leaf.len()).then(|| self.core.restore_index(key, leaf.start + k));
    }

    // 左側のランク
    #[inline]
    fn count_lt_rank(&self, l: usize, r: usize, upper: usize) -> usize {
        let positions = self.positions(l, r);
        returnif!(upper == 0, 0);
        returnif!(!DISTINCT, self.core.count_lt(positions, upper));

        let mut node = WaveletNode::root(positions);
        if upper >= self.values.len() {
            return self.node_count(&node, l);
        }

        let mut result = 0;
        for (bit, level) in (0..self.core.levels.len()).rev().zip(&self.core.levels) {
            let (zero, one) = node.children(level);
            if (upper >> bit) & 1 == 0 {
                node = zero;
            } else {
                result += self.node_count(&zero, l);
                node = one;
            }
        }
        return result;
    }

    /// x未満の値の個数。xが配列になくても良い
    #[inline]
    pub fn count_lt(&self, l: usize, r: usize, x: i64) -> usize {
        return self.count_lt_rank(l, r, self.values.lower_bound(&x));
    }

    /// x以下の値の個数。x+1計算しないので i64::MAXも指定可能
    #[inline]
    pub fn count_le(&self, l: usize, r: usize, x: i64) -> usize {
        return self.count_lt_rank(l, r, self.values.upper_bound(&x));
    }

    /// 値そのものに ±1 せず、座標表の lower/upper boundで端点の包含を変換
    #[inline]
    fn value_keys(&self, bounds: impl RangeBounds<i64>) -> Range<usize> {
        let start = match bounds.start_bound() {
            Bound::Included(x) => self.values.lower_bound(x),
            Bound::Excluded(x) => self.values.upper_bound(x),
            Bound::Unbounded => 0,
        };
        let end = match bounds.end_bound() {
            Bound::Included(x) => self.values.upper_bound(x),
            Bound::Excluded(x) => self.values.lower_bound(x),
            Bound::Unbounded => self.values.len(),
        };
        return start..max(start, end);
    }

    /// low <= 値 < high の個数。low > high なら panic する。
    #[inline]
    pub fn range_freq(&self, l: usize, r: usize, low: i64, high: i64) -> usize {
        assert!(low <= high, "値域 [{low}, {high}) の左端が右端を超えています");
        return self.range_freq_bounds(l, r, low..high);
    }

    /// 開区間・閉区間・片側無限を指定できる個数クエリ。空の値域なら0。
    /// 例: `x..` は x 以上、`..=i64::MAX` は最大値も含む。
    #[inline]
    pub fn range_freq_bounds(&self, l: usize, r: usize, bounds: impl RangeBounds<i64>) -> usize {
        let keys = self.value_keys(bounds);
        return self.count_lt_rank(l, r, keys.end) - self.count_lt_rank(l, r, keys.start);
    }

    /// 値の順位から最後の段の位置まで降りる。等しい値の順序は安定分割で保存される。
    #[inline]
    fn kth_node(&self, l: usize, r: usize, mut k: usize, largest: bool) -> Option<(usize, usize)> {
        let mut node = WaveletNode::root(self.positions(l, r));
        if k >= self.node_count(&node, l) {
            return None;
        }
        for level in &self.core.levels {
            let (zero, one) = node.children(level);
            let (first, second) = if largest { (one, zero) } else { (zero, one) };
            let first_count = self.node_count(&first, l);
            if k < first_count {
                node = first;
            } else {
                // 先の枝に含まれる件数だけ飛ばし、残った枝での順位へ変換する。
                k -= first_count;
                node = second;
            }
        }
        return Some((node.key, node.positions.start + k));
    }

    #[inline]
    pub fn kth_smallest(&self, l: usize, r: usize, k: usize) -> Option<i64> {
        return self.kth_node(l, r, k, false).map(|(key, _)| self.values[key]);
    }

    #[inline]
    pub fn kth_largest(&self, l: usize, r: usize, k: usize) -> Option<i64> {
        return self.kth_node(l, r, k, true).map(|(key, _)| self.values[key]);
    }

    /// (値, 元の位置)。同値は元の位置の昇順。DISTINCT=true では区間内の最左位置。
    #[inline]
    pub fn kth_smallest_with_index(&self, l: usize, r: usize, k: usize) -> Option<(i64, usize)> {
        let (key, i) = self.kth_node(l, r, k, false)?;
        return Some((self.values[key], self.core.restore_index(key, i)));
    }

    /// 大きい値から選ぶ。同値の中では元の位置の小さい方から選ぶ。
    #[inline]
    pub fn kth_largest_with_index(&self, l: usize, r: usize, k: usize) -> Option<(i64, usize)> {
        let (key, i) = self.kth_node(l, r, k, true)?;
        return Some((self.values[key], self.core.restore_index(key, i)));
    }

    #[inline]
    pub fn min(&self, l: usize, r: usize) -> Option<i64> {
        return self.kth_smallest(l, r, 0);
    }

    #[inline]
    pub fn max(&self, l: usize, r: usize) -> Option<i64> {
        return self.kth_largest(l, r, 0);
    }

    /// x 未満の最大値。
    #[inline]
    pub fn prev(&self, l: usize, r: usize, x: i64) -> Option<i64> {
        let k = self.count_lt(l, r, x).checked_sub(1)?;
        return self.kth_smallest(l, r, k);
    }

    /// x 以上の最小値。
    #[inline]
    pub fn next(&self, l: usize, r: usize, x: i64) -> Option<i64> {
        let k = self.count_lt(l, r, x);
        return self.kth_smallest(l, r, k);
    }

    /// 空の枝と値域外の枝を飛ばして、値の葉だけを順に訪ねる。
    /// visit が false を返したら打ち切る。上位・下位の列挙と合計で共用する。
    #[inline]
    fn visit_leaves(
        &self,
        node: WaveletNode,
        wanted: &Range<usize>,
        largest: bool,
        visit: &mut impl FnMut(&WaveletNode) -> bool,
    ) -> bool {
        let remaining = self.core.levels.len() - node.depth;
        let first_key = node.key << remaining;
        let past_last_key = (node.key + 1) << remaining;
        if node.positions.is_empty() || wanted.is_empty() || wanted.end <= first_key || past_last_key <= wanted.start {
            return true;
        }
        returnif!(remaining == 0, visit(&node));
        let (zero, one) = node.children(&self.core.levels[node.depth]);
        let (first, second) = if largest { (one, zero) } else { (zero, one) };
        return self.visit_leaves(first, wanted, largest, visit) && self.visit_leaves(second, wanted, largest, visit);
    }

    #[inline]
    fn extrema(&self, l: usize, r: usize, k: usize, largest: bool) -> Vec<i64> {
        let root = WaveletNode::root(self.positions(l, r));
        let mut result = Vec::new();
        if k != 0 {
            self.visit_leaves(root, &(0..self.values.len()), largest, &mut |node| {
                let take = min(k - result.len(), Self::leaf_count(&node.positions));
                result.resize(result.len() + take, self.values[node.key]);
                result.len() < k
            });
        }
        return result;
    }

    /// 小さい方から最大 k 件を昇順で返す。取り出す件数を t とすると O((t+1)B)
    #[inline]
    pub fn bottom_k(&self, l: usize, r: usize, k: usize) -> Vec<i64> {
        return self.extrema(l, r, k, false);
    }

    /// 大きい方から最大 k 件を降順で返す。取り出す件数を t とすると O((t+1)B)
    #[inline]
    pub fn top_k(&self, l: usize, r: usize, k: usize) -> Vec<i64> {
        return self.extrema(l, r, k, true);
    }

    /// (値, 実際の出現回数) を値の昇順で返す。異なる値が D 個なら O((D+1)B)
    #[inline]
    pub fn histogram(&self, l: usize, r: usize) -> Vec<(i64, usize)> {
        let root = WaveletNode::root(self.positions(l, r));
        let mut result = Vec::new();
        self.visit_leaves(root, &(0..self.values.len()), false, &mut |node| {
            result.push((self.values[node.key], node.positions.len()));
            true
        });
        return result;
    }

    #[inline]
    fn prefix_sum(&self, node: &WaveletNode) -> i128 {
        returnif!(node.positions.is_empty(), 0);
        // 最終段では値がすべて等しいため、その段の累積和は保存しなくてよい。
        if node.depth == self.core.levels.len() {
            return i128::from(self.values[node.key]) * node.positions.len() as i128;
        }
        let prefix = &self.prefix_sums[node.depth];
        return prefix[node.positions.end] - prefix[node.positions.start];
    }

    #[inline]
    fn sum_lt_rank(&self, positions: Range<usize>, upper: usize) -> i128 {
        returnif!(upper == 0, 0);
        let mut node = WaveletNode::root(positions);
        if upper >= self.values.len() {
            return self.prefix_sum(&node);
        }
        let mut sum = 0;
        for (bit, level) in (0..self.core.levels.len()).rev().zip(&self.core.levels) {
            let (zero, one) = node.children(level);
            if (upper >> bit) & 1 == 0 {
                node = zero;
            } else {
                sum += self.prefix_sum(&zero);
                node = one;
            };
        }
        return sum;
    }

    #[inline]
    fn sum_between_ranks(&self, positions: Range<usize>, keys: Range<usize>) -> i128 {
        returnif!(keys.is_empty() || positions.is_empty(), 0);
        if !self.prefix_sums.is_empty() {
            return self.sum_lt_rank(positions.clone(), keys.end) - self.sum_lt_rank(positions, keys.start);
        }
        let mut sum = 0;
        self.visit_leaves(WaveletNode::root(positions), &keys, false, &mut |node| {
            sum += i128::from(self.values[node.key]) * Self::leaf_count(&node.positions) as i128;
            true
        });
        return sum;
    }

    /// 区間内の値の合計。重複除去では各値を1回足す。with_sums なら O(1)
    #[inline]
    pub fn sum(&self, l: usize, r: usize) -> i128 {
        return self.sum_between_ranks(self.positions(l, r), 0..self.values.len());
    }

    /// low <= 値 < high の合計。low > high なら panic する
    #[inline]
    pub fn range_sum(&self, l: usize, r: usize, low: i64, high: i64) -> i128 {
        assert!(low <= high, "値域 [{low}, {high}) の左端が右端を超えています");
        return self.range_sum_bounds(l, r, low..high);
    }

    /// 開区間・閉区間・片側無限を指定できる合計クエリ。空の値域なら0
    /// with_sums なら O(B)、それ以外は含まれる異なる値 D 件に対して O((D+1)B)
    #[inline]
    pub fn range_sum_bounds(&self, l: usize, r: usize, bounds: impl RangeBounds<i64>) -> i128 {
        return self.sum_between_ranks(self.positions(l, r), self.value_keys(bounds));
    }

    #[inline]
    fn sum_k(&self, l: usize, r: usize, mut k: usize, largest: bool) -> Option<i128> {
        let mut node = WaveletNode::root(self.positions(l, r));
        returnif!(k == 0, Some(0));
        returnif!(k > self.node_count(&node, l), None);
        let mut sum = 0;
        if self.prefix_sums.is_empty() {
            self.visit_leaves(node, &(0..self.values.len()), largest, &mut |leaf| {
                let take = min(k, Self::leaf_count(&leaf.positions));
                sum += i128::from(self.values[leaf.key]) * take as i128;
                k -= take;
                k != 0
            });
        } else {
            for level in &self.core.levels {
                let (zero, one) = node.children(level);
                let (first, second) = if largest { (one, zero) } else { (zero, one) };
                if k <= first.positions.len() {
                    node = first;
                } else {
                    // 先の枝をまるごと使えるので、葉まで降りず累積和から取る。
                    sum += self.prefix_sum(&first);
                    k -= first.positions.len();
                    node = second;
                }
            }
            sum += i128::from(self.values[node.key]) * k as i128;
        }
        return Some(sum);
    }

    /// 下位 k 件の合計。件数が足りなければ None。k=0 の合計は0。
    /// with_sums なら O(B)。通常は必要な値の葉を訪ね、重複除去では件数確認に O(L) も使う。
    #[inline]
    pub fn sum_smallest(&self, l: usize, r: usize, k: usize) -> Option<i128> {
        return self.sum_k(l, r, k, false);
    }

    /// 上位 k 件の合計。件数が足りなければ None。k=0 の合計は0。
    /// with_sums なら O(B)。通常は必要な値の葉を訪ね、重複除去では件数確認に O(L) も使う。
    #[inline]
    pub fn sum_largest(&self, l: usize, r: usize, k: usize) -> Option<i128> {
        return self.sum_k(l, r, k, true);
    }
}

impl WaveletMatrix<false> {
    /// 出現回数を数える行列に、1段あたり N+1 個の i128 の累積和を追加する。
    /// 値域の合計や上位・下位 k 件の合計を O(B) で求められる。
    #[inline]
    pub fn with_sums(a: &[i64]) -> Self {
        Self::build(a, true)
    }
}
